/* Exact BGRA row kernels. ARM SIMD is optional; scalar output is the oracle. */
#ifndef FB_FAST_PIXELS_H
#define FB_FAST_PIXELS_H
#include <stdint.h>
#include <string.h>
#if (defined(FB_TEST_NEON) || defined(__aarch64__)) && !defined(FB_DISABLE_NEON)
#include <arm_neon.h>
#define FB_HAVE_NEON 1
#else
#define FB_HAVE_NEON 0
#endif
static inline unsigned fb_mix(unsigned s, unsigned d, unsigned a)
{
    unsigned t=s*a+d*(255-a)+128;
    return (t+(t>>8))>>8;
}
static inline uint32_t fb_mix_pixel(uint32_t old, const unsigned char *src, unsigned a, uint32_t ink)
{
    if(!a) return old;
    unsigned b=src?src[0]:ink&255;
    unsigned g=src?src[1]:(ink>>8)&255;
    unsigned r=src?src[2]:(ink>>16)&255;
    if(a!=255) {b=fb_mix(b,old&255,a);g=fb_mix(g,(old>>8)&255,a);r=fb_mix(r,(old>>16)&255,a);}
    return UINT32_C(0xff000000)|(r<<16)|(g<<8)|b;
}
#if FB_HAVE_NEON
static inline uint8x8_t fb_mix8(uint8x8_t s, uint8x8_t d, uint8x8_t a)
{
    uint16x8_t t=vmull_u8(s,a);
    t=vmlal_u8(t,d,vsub_u8(vdup_n_u8(255),a));
    t=vaddq_u16(t,vdupq_n_u16(128));
    t=vaddq_u16(t,vshrq_n_u16(t,8));
    return vshrn_n_u16(t,8);
}
static inline void fb_blend8(unsigned char *dst, uint8x8x4_t s, uint8x8_t a)
{
    uint8x8x4_t d=vld4_u8(dst),out;
    uint8x8_t zero=vceq_u8(a,vdup_n_u8(0));
    for(int k=0;k<3;++k) out.val[k]=vbsl_u8(zero,d.val[k],fb_mix8(s.val[k],d.val[k],a));
    out.val[3]=vbsl_u8(zero,d.val[3],vdup_n_u8(255));
    vst4_u8(dst,out);
}
#endif
static inline void fb_rgba_row(uint32_t *dst,const unsigned char *src,int w)
{
    int x=0;
#if FB_HAVE_NEON
    for(;x+8<=w;x+=8) {
        uint8x8x4_t s=vld4_u8(src+x*4);
        uint64_t bits=vget_lane_u64(vreinterpret_u64_u8(s.val[3]),0);
        if(!bits) continue;
        if(bits==UINT64_MAX) {memcpy(dst+x,src+x*4,32);continue;}
        fb_blend8((unsigned char *)(dst+x),s,s.val[3]);
    }
#endif
    for(;x<w;++x) {
        unsigned a=src[x*4+3];
        if(a) dst[x]=fb_mix_pixel(dst[x],src+x*4,a,0);
    }
}
static inline void fb_alpha_row(uint32_t *dst,const unsigned char *src,int w,uint32_t ink)
{
    int x=0;
#if FB_HAVE_NEON
    uint8x8x4_t s;
    s.val[0]=vdup_n_u8(ink&255);s.val[1]=vdup_n_u8((ink>>8)&255);
    s.val[2]=vdup_n_u8((ink>>16)&255);s.val[3]=vdup_n_u8(255);
    for(;x+8<=w;x+=8) {
        uint8x8_t a=vld1_u8(src+x);
        uint64_t bits=vget_lane_u64(vreinterpret_u64_u8(a),0);
        if(!bits) continue;
        if(bits==UINT64_MAX) {vst4_u8((unsigned char *)(dst+x),s);continue;}
        fb_blend8((unsigned char *)(dst+x),s,a);
    }
#endif
    for(;x<w;++x) if(src[x]) dst[x]=fb_mix_pixel(dst[x],NULL,src[x],ink);
}
static inline void fb_fast_row(uint32_t *dst,const unsigned char *src,int w,int type,uint32_t ink)
{
    if(type==1) memcpy(dst,src,(size_t)w*4);
    else if(type==2) fb_rgba_row(dst,src,w);
    else fb_alpha_row(dst,src,w,ink);
}
#endif

/* Exact BGRA row kernels. ARM SIMD is optional; scalar output is the oracle. */
#ifndef FB_FAST_PIXELS_H
#define FB_FAST_PIXELS_H
#include <stdint.h>
#include <string.h>
#if (defined(FB_TEST_NEON) || defined(__aarch64__)) && !defined(FB_DISABLE_NEON)
#include <arm_neon.h>
#define FB_HAVE_NEON 1
#else
#define FB_HAVE_NEON 0
#endif
static inline unsigned fb_mix(unsigned s, unsigned d, unsigned a)
{
    unsigned t=s*a+d*(255-a)+128;
    return (t+(t>>8))>>8;
}
static inline uint32_t fb_mix_partial_pixel(uint32_t old, const unsigned char *src, unsigned a, uint32_t ink)
{
#ifndef FB_DISABLE_PACKED
    uint32_t source=ink;
    if(src)source=(uint32_t)src[0]|((uint32_t)src[1]<<8)|((uint32_t)src[2]<<16);
    /* Two independent 16-bit lanes. Bias MUST precede high-byte correction. */
    uint32_t rb=(source&0x00ff00ffu)*a+(old&0x00ff00ffu)*(255-a)+0x00800080u;
    rb=((rb+((rb>>8)&0x00ff00ffu))>>8)&0x00ff00ffu;
    unsigned g=fb_mix((source>>8)&255,(old>>8)&255,a);
    return 0xff000000u|rb|(g<<8);
#else
    unsigned b=src?src[0]:ink&255;
    unsigned g=src?src[1]:(ink>>8)&255;
    unsigned r=src?src[2]:(ink>>16)&255;
    b=fb_mix(b,old&255,a);g=fb_mix(g,(old>>8)&255,a);r=fb_mix(r,(old>>16)&255,a);
    return UINT32_C(0xff000000)|(r<<16)|(g<<8)|b;
#endif
}
static inline uint32_t fb_mix_pixel(uint32_t old,const unsigned char *src,unsigned a,uint32_t ink)
{
    if(!a)return old;
    if(a==255) {
        uint32_t color=src?(uint32_t)src[0]|((uint32_t)src[1]<<8)|((uint32_t)src[2]<<16):ink;
        return 0xff000000u|(color&0x00ffffffu);
    }
    return fb_mix_partial_pixel(old,src,a,ink);
}

#if FB_HAVE_NEON
static inline uint8x8_t fb_mix8(uint8x8_t s, uint8x8_t d, uint8x8_t a)
{
    uint16x8_t t=vmull_u8(s,a);
    t=vmlal_u8(t,d,vsub_u8(vdup_n_u8(255),a));
    t=vaddq_u16(t,vdupq_n_u16(128));
    t=vaddq_u16(t,vshrq_n_u16(t,8));
    return vshrn_n_u16(t,8);
}
static inline void fb_blend8(unsigned char *dst, uint8x8x4_t s, uint8x8_t a)
{
    uint8x8x4_t d=vld4_u8(dst),out;
    uint8x8_t zero=vceq_u8(a,vdup_n_u8(0));
    for(int k=0;k<3;++k) out.val[k]=vbsl_u8(zero,d.val[k],fb_mix8(s.val[k],d.val[k],a));
    out.val[3]=vbsl_u8(zero,d.val[3],vdup_n_u8(255));
    vst4_u8(dst,out);
}
#endif
static inline void fb_rgba_row(uint32_t *dst,const unsigned char *src,int w)
{
    int x=0;
#if FB_HAVE_NEON
    for(;x+8<=w;x+=8) {
        uint8x8x4_t s=vld4_u8(src+x*4);
        uint64_t bits=vget_lane_u64(vreinterpret_u64_u8(s.val[3]),0);
        if(!bits) continue;
        if(bits==UINT64_MAX) {memcpy(dst+x,src+x*4,32);continue;}
        fb_blend8((unsigned char *)(dst+x),s,s.val[3]);
    }
#endif
    for(;x<w;++x) {
        unsigned a=src[x*4+3];
        if(a) dst[x]=fb_mix_pixel(dst[x],src+x*4,a,0);
    }
}
static inline void fb_alpha_row(uint32_t *dst,const unsigned char *src,int w,uint32_t ink)
{
    int x=0;
#if FB_HAVE_NEON
    uint8x8x4_t s;
    s.val[0]=vdup_n_u8(ink&255);s.val[1]=vdup_n_u8((ink>>8)&255);
    s.val[2]=vdup_n_u8((ink>>16)&255);s.val[3]=vdup_n_u8(255);
    for(;x+8<=w;x+=8) {
        uint8x8_t a=vld1_u8(src+x);
        uint64_t bits=vget_lane_u64(vreinterpret_u64_u8(a),0);
        if(!bits) continue;
        if(bits==UINT64_MAX) {vst4_u8((unsigned char *)(dst+x),s);continue;}
        fb_blend8((unsigned char *)(dst+x),s,a);
    }
#endif
    for(;x<w;++x) if(src[x]) dst[x]=fb_mix_pixel(dst[x],NULL,src[x],ink);
}
static inline void fb_fast_row(uint32_t *dst,const unsigned char *src,int w,int type,uint32_t ink)
{
    if(type==1) memcpy(dst,src,(size_t)w*4);
    else if(type==2) fb_rgba_row(dst,src,w);
    else fb_alpha_row(dst,src,w,ink);
}
#endif

/* Exact BGRA row kernels. ARM SIMD is optional; scalar output is the oracle. */
#ifndef FB_FAST_PIXELS_H
#define FB_FAST_PIXELS_H
#include <stdint.h>
#include <string.h>
#if (defined(FB_TEST_NEON) || defined(__aarch64__)) && !defined(FB_DISABLE_NEON)
#include <arm_neon.h>
#define FB_HAVE_NEON 1
#else
#define FB_HAVE_NEON 0
#endif
static inline unsigned fb_mix(unsigned s, unsigned d, unsigned a)
{
    unsigned t=s*a+d*(255-a)+128;
    return (t+(t>>8))>>8;
}
static inline uint32_t fb_mix_partial_pixel(uint32_t old, const unsigned char *src, unsigned a, uint32_t ink)
{
#ifndef FB_DISABLE_PACKED
    uint32_t source=ink;
    if(src)source=(uint32_t)src[0]|((uint32_t)src[1]<<8)|((uint32_t)src[2]<<16);
    /* Two independent 16-bit lanes. Bias MUST precede high-byte correction. */
    uint32_t rb=(source&0x00ff00ffu)*a+(old&0x00ff00ffu)*(255-a)+0x00800080u;
    rb=((rb+((rb>>8)&0x00ff00ffu))>>8)&0x00ff00ffu;
    unsigned g=fb_mix((source>>8)&255,(old>>8)&255,a);
    return 0xff000000u|rb|(g<<8);
#else
    unsigned b=src?src[0]:ink&255;
    unsigned g=src?src[1]:(ink>>8)&255;
    unsigned r=src?src[2]:(ink>>16)&255;
    b=fb_mix(b,old&255,a);g=fb_mix(g,(old>>8)&255,a);r=fb_mix(r,(old>>16)&255,a);
    return UINT32_C(0xff000000)|(r<<16)|(g<<8)|b;
#endif
}
static inline uint32_t fb_mix_pixel(uint32_t old,const unsigned char *src,unsigned a,uint32_t ink)
{
    if(!a)return old;
    if(a==255) {
        uint32_t color=src?(uint32_t)src[0]|((uint32_t)src[1]<<8)|((uint32_t)src[2]<<16):ink;
        return 0xff000000u|(color&0x00ffffffu);
    }
    return fb_mix_partial_pixel(old,src,a,ink);
}

#if FB_HAVE_NEON
/* Four complete pixels only: 16-byte BGRA and exact 4-byte alpha loads.
   32-bit lanes avoid deinterleaving and never touch an eight-pixel tail. */
#ifndef FB_DISABLE_FOUR_LANE
static inline uint32x4_t fb_load4_rgba(const unsigned char *p)
{
    return vreinterpretq_u32_u8(vld1q_u8(p));
}
static inline uint32x4_t fb_load4_alpha(const unsigned char *p)
{
    uint32_t a;memcpy(&a,p,4);
    return vmovl_u16(vget_low_u16(vmovl_u8(vcreate_u8(a))));
}
static inline uint32x4_t fb_mix4_channel(uint32x4_t s,uint32x4_t d,uint32x4_t a)
{
    uint32x4_t t=vmlaq_u32(vmulq_u32(s,a),d,vsubq_u32(vdupq_n_u32(255),a));
    t=vaddq_u32(t,vdupq_n_u32(128));
    return vshrq_n_u32(vaddq_u32(t,vshrq_n_u32(t,8)),8);
}
/* Each packed half remains <= 65407 after correction: no lane carry.
   Keep the same /255 rounding; this is not premultiplied /256 blending. */
static inline uint32x4_t fb_round4_rb_candidate(uint32x4_t t)
{
    uint32x4_t mask=vdupq_n_u32(0x00ff00ffu);
    t=vaddq_u32(t,vdupq_n_u32(0x00800080u));
    return vandq_u32(vshrq_n_u32(vaddq_u32(t,vandq_u32(vshrq_n_u32(t,8),mask)),8),mask);
}
static inline void fb_blend4(uint32_t *dst,uint32x4_t s,uint32x4_t a,int partial)
{
    uint32x4_t d=vld1q_u32(dst),mask=vdupq_n_u32(255);
    #ifndef FB_DISABLE_PACKED_FOUR
    uint32x4_t rbmask=vdupq_n_u32(0x00ff00ffu);
    uint32x4_t rb=fb_round4_rb_candidate(vmlaq_u32(vmulq_u32(vandq_u32(s,rbmask),a),
        vandq_u32(d,rbmask),vsubq_u32(vdupq_n_u32(255),a)));
    uint32x4_t g=fb_mix4_channel(vandq_u32(vshrq_n_u32(s,8),mask),vandq_u32(vshrq_n_u32(d,8),mask),a);
    uint32x4_t out=vorrq_u32(vdupq_n_u32(0xff000000u),vorrq_u32(rb,vshlq_n_u32(g,8)));
    #else
    uint32x4_t b=fb_mix4_channel(vandq_u32(s,mask),vandq_u32(d,mask),a);
    uint32x4_t g=fb_mix4_channel(vandq_u32(vshrq_n_u32(s,8),mask),vandq_u32(vshrq_n_u32(d,8),mask),a);
    uint32x4_t r=fb_mix4_channel(vandq_u32(vshrq_n_u32(s,16),mask),vandq_u32(vshrq_n_u32(d,16),mask),a);
    uint32x4_t out=vorrq_u32(vdupq_n_u32(0xff000000u),vorrq_u32(b,vorrq_u32(vshlq_n_u32(g,8),vshlq_n_u32(r,16))));
    #endif
    if(!partial)out=vbslq_u32(vceqq_u32(a,vdupq_n_u32(0)),d,out);
    vst1q_u32(dst,out);
}
#endif
/* For 0<=t<=65025:
   ((t + round(t/256)) + 128)>>8 == (t+128+((t+128)>>8))>>8.
   Rounded shift-accumulate plus rounded narrow preserves exact /255 rounding. */
static inline uint8x8_t fb_round8_candidate(uint16x8_t t)
{
    #ifndef FB_DISABLE_SHORT_ROUND
    return vrshrn_n_u16(vrsraq_n_u16(t,t,8),8);
    #else
    t=vaddq_u16(t,vdupq_n_u16(128));
    t=vaddq_u16(t,vshrq_n_u16(t,8));
    return vshrn_n_u16(t,8);
    #endif
}
static inline uint8x8_t fb_mix8(uint8x8_t s, uint8x8_t d, uint8x8_t a)
{
    uint16x8_t t=vmull_u8(s,a);
    t=vmlal_u8(t,d,vsub_u8(vdup_n_u8(255),a));
    return fb_round8_candidate(t);
}
static inline void fb_blend8(unsigned char *dst, uint8x8x4_t s, uint8x8_t a)
{
    uint8x8x4_t d=vld4_u8(dst),out;
    uint8x8_t zero=vceq_u8(a,vdup_n_u8(0));
    for(int k=0;k<3;++k) out.val[k]=vbsl_u8(zero,d.val[k],fb_mix8(s.val[k],d.val[k],a));
    out.val[3]=vbsl_u8(zero,d.val[3],vdup_n_u8(255));
    vst4_u8(dst,out);
}
#endif
static inline void fb_rgba_row(uint32_t *dst,const unsigned char *src,int w)
{
    int x=0;
#if FB_HAVE_NEON
    for(;x+8<=w;x+=8) {
        uint8x8x4_t s=vld4_u8(src+x*4);
        uint64_t bits=vget_lane_u64(vreinterpret_u64_u8(s.val[3]),0);
        if(!bits) continue;
        if(bits==UINT64_MAX) {memcpy(dst+x,src+x*4,32);continue;}
        fb_blend8((unsigned char *)(dst+x),s,s.val[3]);
    }
#ifndef FB_DISABLE_FOUR_LANE
    if(x+4<=w) {
        uint32x4_t s=fb_load4_rgba(src+x*4);
        fb_blend4(dst+x,s,vshrq_n_u32(s,24),0);x+=4;
    }
#endif
#endif
    for(;x<w;++x) {
        unsigned a=src[x*4+3];
        if(a) dst[x]=fb_mix_pixel(dst[x],src+x*4,a,0);
    }
}
static inline void fb_alpha_row(uint32_t *dst,const unsigned char *src,int w,uint32_t ink)
{
    int x=0;
#if FB_HAVE_NEON
    uint8x8x4_t s;
    s.val[0]=vdup_n_u8(ink&255);s.val[1]=vdup_n_u8((ink>>8)&255);
    s.val[2]=vdup_n_u8((ink>>16)&255);s.val[3]=vdup_n_u8(255);
    for(;x+8<=w;x+=8) {
        uint8x8_t a=vld1_u8(src+x);
        uint64_t bits=vget_lane_u64(vreinterpret_u64_u8(a),0);
        if(!bits) continue;
        if(bits==UINT64_MAX) {vst4_u8((unsigned char *)(dst+x),s);continue;}
        fb_blend8((unsigned char *)(dst+x),s,a);
    }
#ifndef FB_DISABLE_FOUR_LANE
    if(x+4<=w) {fb_blend4(dst+x,vdupq_n_u32(ink),fb_load4_alpha(src+x),0);x+=4;}
#endif
#endif
    for(;x<w;++x) if(src[x]) dst[x]=fb_mix_pixel(dst[x],NULL,src[x],ink);
}
static inline void fb_fast_row(uint32_t *dst,const unsigned char *src,int w,int type,uint32_t ink)
{
    if(type==1) memcpy(dst,src,(size_t)w*4);
    else if(type==2) fb_rgba_row(dst,src,w);
    else fb_alpha_row(dst,src,w,ink);
}
#endif

#ifndef FB_GEOMETRY_BATCH_API_V9_H
#define FB_GEOMETRY_BATCH_API_V9_H
/* One ordered group of opaque replacement draws.  End the group before any
 * other draw or fb_update.  Ownership is local to begin/end, NULL is valid.
 * Every accepted operation returns 1, including clipped-away operations. */
typedef struct fb_geometry_batch fb_geometry_batch;
fb_geometry_batch *fb_geometry_batch_begin(void);
int fb_geometry_batch_rect(fb_geometry_batch *,int,int,int,int,int);
int fb_geometry_batch_line(fb_geometry_batch *,int,int,int,int,int);
void fb_geometry_batch_end(fb_geometry_batch *);
#endif

#ifndef FB_GEOMETRY_BATCH_V9_H
#define FB_GEOMETRY_BATCH_V9_H
#include "geometry_batch_api_v9.h"
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#ifdef FB_DISABLE_STATS
#define FB_GEOMETRY_COUNT(expression) ((void)0)
#else
#define FB_GEOMETRY_COUNT(expression) do {expression;} while(0)
#endif
#ifndef FB_GEOMETRY_BATCH_CAPACITY
#define FB_GEOMETRY_BATCH_CAPACITY 16384u
#endif
#ifndef FB_GEOMETRY_SPAN_LIMIT
#define FB_GEOMETRY_SPAN_LIMIT 1048576u
#endif
#ifndef FB_GEOMETRY_MALLOC
#define FB_GEOMETRY_MALLOC malloc
#define FB_GEOMETRY_CALLOC calloc
#define FB_GEOMETRY_REALLOC realloc
#define FB_GEOMETRY_FREE free
#endif
struct fb_geometry_span {int y,left,right;uint32_t color;};
struct fb_geometry_batch {
    struct fb_geometry_span *spans;
    unsigned count,capacity,commands,row_counts[SCREEN_HEIGHT],row_last[SCREEN_HEIGHT];
    uint64_t submitted_pixels,written_pixels,flushes,fallbacks,generated_spans,retained_spans;
};
static inline void fb_geometry_fill(int y,int left,int right,uint32_t color)
{
    uint32_t *p=(uint32_t *)DRAW_BUF+(size_t)y*SCREEN_WIDTH+left;
    int n=right-left,i=0;
#if FB_HAVE_NEON
    uint32x4_t v=vdupq_n_u32(color);
    for(;i+16<=n;i+=16){vst1q_u32(p+i,v);vst1q_u32(p+i+4,v);vst1q_u32(p+i+8,v);vst1q_u32(p+i+12,v);}
    for(;i+4<=n;i+=4)vst1q_u32(p+i,v);
#endif
    for(;i<n;++i)p[i]=color;
}
#ifdef FB_GEOMETRY_DSU
static unsigned fb_geometry_find(unsigned *parent,unsigned x)
{
    unsigned root=x;
    while(parent[root]!=root)root=parent[root];
    while(parent[x]!=x){unsigned next=parent[x];parent[x]=root;x=next;}
    return root;
}
static unsigned fb_geometry_join(unsigned *parent,unsigned *size,unsigned *end,unsigned x,unsigned y)
{
    unsigned a=fb_geometry_find(parent,x),b=fb_geometry_find(parent,y);
    if(a!=b){if(size[a]<size[b]){unsigned t=a;a=b;b=t;}parent[b]=a;size[a]+=size[b];if(end[a]<end[b])end[a]=end[b];}
    return end[a];
}
#endif
static uint64_t fb_geometry_render_row(const fb_geometry_batch *batch,const unsigned *index,unsigned first,unsigned last,int y)
{
    uint64_t written=0;
#ifdef FB_GEOMETRY_DSU
    unsigned parent[SCREEN_WIDTH+1],size[SCREEN_WIDTH+1],end[SCREEN_WIDTH+1];
    for(unsigned i=0;i<=SCREEN_WIDTH;++i){parent[i]=end[i]=i;size[i]=1;}
    for(unsigned j=last;j>first;--j){
        const struct fb_geometry_span *s=&batch->spans[index[j-1]];
        unsigned x=end[fb_geometry_find(parent,(unsigned)s->left)];
        while(x<(unsigned)s->right){
            DRAW_BUF[(size_t)y*SCREEN_WIDTH+x]=(int)s->color;FB_GEOMETRY_COUNT(++written);
            x=fb_geometry_join(parent,size,end,x,x+1);
        }
        if(end[fb_geometry_find(parent,0)]==SCREEN_WIDTH)break;
    }
#else
    uint64_t covered[(SCREEN_WIDTH+63)/64]={0};
    unsigned remaining=SCREEN_WIDTH;
    for(unsigned j=last;j>first;--j){
        const struct fb_geometry_span *s=&batch->spans[index[j-1]];
        unsigned lo=(unsigned)s->left>>6,hi=((unsigned)s->right-1)>>6;
        int run_left=-1,run_right=0;
        for(unsigned word=lo;word<=hi;++word){
            unsigned left=word==lo?((unsigned)s->left&63u):0u;
            unsigned right=word==hi?(((unsigned)s->right-1)&63u)+1u:64u;
            uint64_t mask=(UINT64_MAX<<left)&(right==64u?UINT64_MAX:((UINT64_C(1)<<right)-1));
            uint64_t todo=mask&~covered[word];covered[word]|=mask;
            while(todo){
                unsigned start=(unsigned)__builtin_ctzll(todo);
                uint64_t suffix=todo>>start;
                unsigned length=~suffix?(unsigned)__builtin_ctzll(~suffix):64u;
                int l=(int)(word*64u+start),r=l+(int)length;
                if(l==run_right && run_left>=0)run_right=r;
                else {if(run_left>=0)fb_geometry_fill(y,run_left,run_right,s->color);run_left=l;run_right=r;}
                FB_GEOMETRY_COUNT(written+=length);remaining-=length;
                if(length==64u)todo=0;else todo&=~(((UINT64_C(1)<<length)-1)<<start);
            }
        }
        if(run_left>=0)fb_geometry_fill(y,run_left,run_right,s->color);
        if(!remaining)break;
    }
#endif
    return written;
}
static void fb_geometry_flush(fb_geometry_batch *batch)
{
    if(!batch || !batch->count)return;
    unsigned offset[SCREEN_HEIGHT+1],cursor[SCREEN_HEIGHT];
    int left=SCREEN_WIDTH,right=0,top=SCREEN_HEIGHT,bottom=0;
    offset[0]=0;
    for(int y=0;y<SCREEN_HEIGHT;++y){offset[y+1]=offset[y]+batch->row_counts[y];cursor[y]=offset[y];}
    for(unsigned i=0;i<batch->count;++i){const struct fb_geometry_span *s=&batch->spans[i];
        if(left>s->left)left=s->left;
        if(right<s->right)right=s->right;
        if(top>s->y)top=s->y;
        if(bottom<s->y+1)bottom=s->y+1;}
    _begin_draw(left,top,right-left,bottom-top);
#ifdef FB_GEOMETRY_FAIL_INDEX
    unsigned *index=NULL;
#else
    unsigned *index=(unsigned *)FB_GEOMETRY_MALLOC((size_t)batch->count*sizeof(*index));
#endif
    uint64_t written=0;
    if(!index){
        FB_GEOMETRY_COUNT(++batch->fallbacks);
        for(unsigned i=0;i<batch->count;++i){const struct fb_geometry_span *s=&batch->spans[i];fb_geometry_fill(s->y,s->left,s->right,s->color);FB_GEOMETRY_COUNT(written+=(unsigned)(s->right-s->left));}
    }else{
        for(unsigned i=0;i<batch->count;++i)index[cursor[batch->spans[i].y]++]=i;
#ifdef _OPENMP
#ifdef FB_DISABLE_STATS
#pragma omp parallel for schedule(static) if(batch->count>64 && bottom-top>32)
#else
#pragma omp parallel for schedule(static) reduction(+:written) if(batch->count>64 && bottom-top>32)
#endif
#endif
        for(int y=top;y<bottom;++y){
            uint64_t row_written=fb_geometry_render_row(batch,index,offset[y],offset[y+1],y);
            FB_GEOMETRY_COUNT(written+=row_written);(void)row_written;
        }
        FB_GEOMETRY_FREE(index);
    }
    FB_GEOMETRY_COUNT(batch->written_pixels+=written;++batch->flushes);(void)written;batch->count=0;batch->commands=0;
    memset(batch->row_counts,0,sizeof(batch->row_counts));
}
static void fb_geometry_emit(fb_geometry_batch *batch,int y,int left,int right,uint32_t color)
{
    if(left>=right)return;
    FB_GEOMETRY_COUNT(++batch->generated_spans;batch->submitted_pixels+=(unsigned)(right-left));
#ifndef FB_DISABLE_GEOMETRY_COALESCE
    /* Only the immediately preceding command on THIS row may be merged.
     * Same color plus intersecting/adjacent spans has exactly the same union;
     * any intervening different color or separated span prevents merging. */
    if(batch->row_counts[y]){
        struct fb_geometry_span *last=&batch->spans[batch->row_last[y]];
        if(last->color==color && last->left<=right && left<=last->right){
            if(last->left>left)last->left=left;
            if(last->right<right)last->right=right;
            return;
        }
    }
#endif
    if(batch->count>=FB_GEOMETRY_SPAN_LIMIT)fb_geometry_flush(batch);
    if(batch->count==batch->capacity){
        unsigned cap=batch->capacity?batch->capacity*2u:1024u;
        if(cap>FB_GEOMETRY_SPAN_LIMIT)cap=FB_GEOMETRY_SPAN_LIMIT;
        struct fb_geometry_span *p=cap?(struct fb_geometry_span *)FB_GEOMETRY_REALLOC(batch->spans,(size_t)cap*sizeof(*p)):NULL;
        if(!p){
            fb_geometry_flush(batch);_begin_draw(left,y,right-left,1);fb_geometry_fill(y,left,right,color);
            FB_GEOMETRY_COUNT(++batch->fallbacks;batch->written_pixels+=(unsigned)(right-left));return;
        }
        batch->spans=p;batch->capacity=cap;
    }
    batch->row_last[y]=batch->count;
    batch->spans[batch->count++]=(struct fb_geometry_span){y,left,right,color};++batch->row_counts[y];FB_GEOMETRY_COUNT(++batch->retained_spans);
}
/* int32 endpoint products are formed wide.  The nonnegative numerators below
 * are at most (2^32-1)^2+(2^31-1), so the actual quotient uses native uint64.
 * Signed ceil handles the negative half-phase at the first row exactly. */
static inline int64_t fb_geometry_ceil(__int128 n,uint64_t d)
{
    if(n<0)return -(int64_t)((uint64_t)(-n)/d);
    uint64_t u=(uint64_t)n;
    return (int64_t)(u/d+(u%d!=0));
}
static inline int64_t fb_geometry_minor(int64_t n,int sign,uint64_t delta,uint64_t q,uint64_t length)
{
    if(!length)return n;
    __int128 product=(__int128)delta*q+length/2;
    return n+sign*(int64_t)((uint64_t)product/length);
}
fb_geometry_batch *fb_geometry_batch_begin(void)
{
#ifdef FB_DISABLE_GEOMETRY_BATCH
    return NULL;
#else
    return (fb_geometry_batch *)FB_GEOMETRY_CALLOC(1,sizeof(fb_geometry_batch));
#endif
}
int fb_geometry_batch_rect(fb_geometry_batch *batch,int x,int y,int w,int h,int color)
{
    if(!batch){fb_draw_rect(x,y,w,h,color);return 1;}
    if(batch->commands>=FB_GEOMETRY_BATCH_CAPACITY)fb_geometry_flush(batch);
    ++batch->commands;if(w<=0 || h<=0)return 1;
    int64_t l=x,r=(int64_t)x+w,t=y,b=(int64_t)y+h;
    if(l<0)l=0;
    if(r>SCREEN_WIDTH)r=SCREEN_WIDTH;
    if(t<0)t=0;
    if(b>SCREEN_HEIGHT)b=SCREEN_HEIGHT;
    if(l>=r || t>=b)return 1;
    for(int row=(int)t;row<(int)b;++row)fb_geometry_emit(batch,row,(int)l,(int)r,(uint32_t)color);
    return 1;
}
int fb_geometry_batch_line(fb_geometry_batch *batch,int x1,int y1,int x2,int y2,int color)
{
    if(!batch){fb_draw_line(x1,y1,x2,y2,color);return 1;}
    if(batch->commands>=FB_GEOMETRY_BATCH_CAPACITY)fb_geometry_flush(batch);
    ++batch->commands;
    int64_t dx=(int64_t)x2-x1,dy=(int64_t)y2-y1;
    int steep=llabs(dy)>llabs(dx),sign;
    int64_t m1=steep?y1:x1,m2=steep?y2:x2,n1=steep?x1:y1,n2=steep?x2:y2;
    if(m1>m2){int64_t t=m1;m1=m2;m2=t;t=n1;n1=n2;n2=t;}
    uint64_t length=(uint64_t)(m2-m1),delta=(uint64_t)llabs(n2-n1);
    sign=n2<n1?-1:1;
#ifdef FB_DISABLE_ANALYTIC_LINES
    int64_t first=m1<0?0:m1,last=m2,limit=steep?SCREEN_HEIGHT:SCREEN_WIDTH;
    if(last>=limit)last=limit-1;
    if(first>last)return 1;
    uint64_t q=(uint64_t)(first-m1),numerator=delta*q+length/2;
    int64_t minor=length?n1+sign*(int64_t)(numerator/length):n1;
    uint64_t error=length?numerator%length:0;
    int run_y=-1,run_l=0,run_r=0;
    for(int64_t major=first;major<=last;++major){
        int64_t x=steep?minor:major,y=steep?major:minor;
        if(x>=0 && x<SCREEN_WIDTH && y>=0 && y<SCREEN_HEIGHT){
            if((int)y==run_y && (int)x==run_r)++run_r;
            else{if(run_y>=0)fb_geometry_emit(batch,run_y,run_l,run_r,(uint32_t)color);run_y=(int)y;run_l=(int)x;run_r=(int)x+1;}
        }
        error+=delta;if(length && error>=length){error-=length;minor+=sign;}
    }
    if(run_y>=0)fb_geometry_emit(batch,run_y,run_l,run_r,(uint32_t)color);
#else
    int64_t qmin=m1<0?-m1:0,qmax=(int64_t)length;
    int64_t major_limit=steep?SCREEN_HEIGHT:SCREEN_WIDTH;
    if(qmax>major_limit-1-m1)qmax=major_limit-1-m1;
    if(qmin>qmax)return 1;
    if(steep){
        if(!delta){if(n1<0 || n1>=SCREEN_WIDTH)return 1;}
        else{
            int64_t kmin=sign>0?-n1:n1-(SCREEN_WIDTH-1),kmax=sign>0?SCREEN_WIDTH-1-n1:n1;
            if(kmin<0)kmin=0;
            if(kmax>(int64_t)delta)kmax=(int64_t)delta;
            if(kmin>kmax)return 1;
            if(kmin>0){int64_t q=fb_geometry_ceil((__int128)kmin*length-length/2,delta);if(qmin<q)qmin=q;}
            if(kmax<(int64_t)delta){int64_t q=fb_geometry_ceil((__int128)(kmax+1)*length-length/2,delta)-1;if(qmax>q)qmax=q;}
        }
        if(qmin>qmax)return 1;
        /* One initial quotient then the original exact Bresenham remainder
         * recurrence.  No divide is executed for subsequent target rows. */
        uint64_t numerator=(uint64_t)((__int128)delta*qmin+length/2);
        int64_t minor=n1+sign*(int64_t)(numerator/length);
        uint64_t remainder=numerator%length;
        for(int64_t q=qmin;q<=qmax;++q){
            fb_geometry_emit(batch,(int)(m1+q),(int)minor,(int)minor+1,(uint32_t)color);
            remainder+=delta;if(remainder>=length){remainder-=length;minor+=sign;}
        }
    }else if(!delta){
        if(n1>=0 && n1<SCREEN_HEIGHT)fb_geometry_emit(batch,(int)n1,(int)(m1+qmin),(int)(m1+qmax+1),(uint32_t)color);
    }else{
        int64_t a=fb_geometry_minor(n1,sign,delta,(uint64_t)qmin,length),b=fb_geometry_minor(n1,sign,delta,(uint64_t)qmax,length);
        int64_t first=a<b?a:b,last=a>b?a:b;if(first<0)first=0;if(last>=SCREEN_HEIGHT)last=SCREEN_HEIGHT-1;
        if(first>last)return 1;
        /* Traverse k in increasing order even for descending lines.  Given
         * c=ceil(n/d), deficit=c*d-n in [0,d), adding L changes c by floor(L/d)
         * plus one carry iff (L%d)>deficit.  This exactly reproduces both ceil
         * bounds with O(1) setup divides rather than two divides per span. */
        int64_t y=sign>0?first:last,k=(y-n1)*sign;
        __int128 numerator=(__int128)k*length-length/2;
        int64_t boundary=fb_geometry_ceil(numerator,delta);
        uint64_t deficit=(uint64_t)((__int128)boundary*delta-numerator);
        uint64_t step=length/delta,carry_step=length%delta;
        for(int64_t row=first;row<=last;++row,y+=sign){
            int carry=carry_step>deficit;
            int64_t next=boundary+(int64_t)step+carry;
            int64_t lo=boundary,hi=next-1;
            deficit=carry?deficit+delta-carry_step:deficit-carry_step;boundary=next;
            if(lo<qmin)lo=qmin;
            if(hi>qmax)hi=qmax;
            if(lo<=hi)fb_geometry_emit(batch,(int)y,(int)(m1+lo),(int)(m1+hi+1),(uint32_t)color);
        }
    }
#endif
    return 1;
}
void fb_geometry_batch_end(fb_geometry_batch *batch)
{
    if(!batch)return;
    fb_geometry_flush(batch);FB_GEOMETRY_FREE(batch->spans);FB_GEOMETRY_FREE(batch);
}
#endif

/* Valid on-screen coordinates only; callers keep the original clipped fallback. */
static void fb_fill_rect_inside(int x,int y,int w,int h,int color)
{
    _begin_draw(x,y,w,h);
    #if FB_HAVE_NEON
    uint32x4_t value=vdupq_n_u32((uint32_t)color);
    #endif
    for(int row=0;row<h;row++) {
        uint32_t *dst=(uint32_t *)(DRAW_BUF+(y+row)*SCREEN_WIDTH+x);
        int col=0;
        #if FB_HAVE_NEON
        for(;col+16<=w;col+=16) {
            vst1q_u32(dst+col,value);vst1q_u32(dst+col+4,value);
            vst1q_u32(dst+col+8,value);vst1q_u32(dst+col+12,value);
        }
        for(;col+4<=w;col+=4)vst1q_u32(dst+col,value);
        #endif
        for(;col<w;col++)dst[col]=(uint32_t)color;
    }
}
static void fb_line_inside(int x1,int y1,int x2,int y2,int color)
{
    int dx=x2-x1,dy=y2-y1,steep=abs(dy)>abs(dx);
    int major1=steep?y1:x1,major2=steep?y2:x2;
    int minor1=steep?x1:y1,minor2=steep?x2:y2;
    if(major1>major2) {
        int temp=major1;major1=major2;major2=temp;
        temp=minor1;minor1=minor2;minor2=temp;
    }
    int left=x1<x2?x1:x2,top=y1<y2?y1:y2;
    _begin_draw(left,top,abs(dx)+1,abs(dy)+1);
    int length=major2-major1,distance=abs(minor2-minor1);
    int *pixel=DRAW_BUF+(steep?major1:minor1)*SCREEN_WIDTH+(steep?minor1:major1);
    if(!length){*pixel=color;return;}
    int error=length/2,major_step=steep?SCREEN_WIDTH:1;
    int minor_step=(minor2<minor1?-1:1)*(steep?1:SCREEN_WIDTH);
    for(int i=0;i<length;i++) {
        *pixel=color;error+=distance;pixel+=major_step;
        if(error>=length){error-=length;pixel+=minor_step;}
    }
    *pixel=color;
}

/* Valid on-screen coordinates only; callers keep the original clipped fallback. */
static inline void fb_fill_rect_inside(int x,int y,int w,int h,int color)
{
    _begin_draw(x,y,w,h);
    #if FB_HAVE_NEON
    uint32x4_t value=vdupq_n_u32((uint32_t)color);
    #endif
    for(int row=0;row<h;row++) {
        uint32_t *dst=(uint32_t *)(DRAW_BUF+(y+row)*SCREEN_WIDTH+x);
        int col=0;
        #if FB_HAVE_NEON
        for(;col+16<=w;col+=16) {
            vst1q_u32(dst+col,value);vst1q_u32(dst+col+4,value);
            vst1q_u32(dst+col+8,value);vst1q_u32(dst+col+12,value);
        }
        for(;col+4<=w;col+=4)vst1q_u32(dst+col,value);
        #endif
        for(;col<w;col++)dst[col]=(uint32_t)color;
    }
}
static inline void fb_line_inside(int x1,int y1,int x2,int y2,int color)
{
    int dx=x2-x1,dy=y2-y1,steep=abs(dy)>abs(dx);
    int major1=steep?y1:x1,major2=steep?y2:x2;
    int minor1=steep?x1:y1,minor2=steep?x2:y2;
    if(major1>major2) {
        int temp=major1;major1=major2;major2=temp;
        temp=minor1;minor1=minor2;minor2=temp;
    }
    int left=x1<x2?x1:x2,top=y1<y2?y1:y2;
    _begin_draw(left,top,abs(dx)+1,abs(dy)+1);
    int length=major2-major1,distance=abs(minor2-minor1);
    int *pixel=DRAW_BUF+(steep?major1:minor1)*SCREEN_WIDTH+(steep?minor1:major1);
    if(!length){*pixel=color;return;}
    int error=length/2,major_step=steep?SCREEN_WIDTH:1;
    int minor_step=(minor2<minor1?-1:1)*(steep?1:SCREEN_WIDTH);
    for(int i=0;i<length;i++) {
        *pixel=color;error+=distance;pixel+=major_step;
        if(error>=length){error-=length;pixel+=minor_step;}
    }
    *pixel=color;
}

#include "common.h"
#include <sys/ioctl.h>
#include <linux/fb.h>
#include <linux/kd.h>
#include <linux/vt.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdio.h>
#include <sys/mman.h>
#include <string.h>

static int LCD_FB_FD;
static int *LCD_FB_BUF;
static int LCD_FB_LINELEN;
static int DRAW_BUF[SCREEN_WIDTH*SCREEN_HEIGHT];

static struct area {
	int x1, x2, y1, y2;
} update_area = {0,0,0,0};

#define AREA_SET_EMPTY(pa) do {\
	(pa)->x1 = SCREEN_WIDTH;\
	(pa)->x2 = 0;\
	(pa)->y1 = SCREEN_HEIGHT;\
	(pa)->y2 = 0;\
} while(0)

void fb_init(char *dev)
{
	int fd;
	struct fb_fix_screeninfo fb_fix;
	struct fb_var_screeninfo fb_var;

	if(LCD_FB_BUF != NULL) return; /*already done*/

	//进入终端图形模式
	fd = open("/dev/tty0",O_RDWR,0);
	ioctl(fd, KDSETMODE, KD_GRAPHICS);
	close(fd);

	//First: Open the device
	if((fd = open(dev, O_RDWR)) < 0){
		printf("Unable to open framebuffer %s, errno = %d\n", dev, errno);
		return;
	}
	if(ioctl(fd, FBIOGET_FSCREENINFO, &fb_fix) < 0){
		printf("Unable to FBIOGET_FSCREENINFO %s\n", dev);
		return;
	}
	if(ioctl(fd, FBIOGET_VSCREENINFO, &fb_var) < 0){
		printf("Unable to FBIOGET_VSCREENINFO %s\n", dev);
		return;
	}

	printf("framebuffer info: bits_per_pixel=%u,size=(%d,%d),virtual_pos_size=(%d,%d)(%d,%d),line_length=%u,smem_len=%u\n",
		fb_var.bits_per_pixel, fb_var.xres, fb_var.yres, fb_var.xoffset, fb_var.yoffset,
		fb_var.xres_virtual, fb_var.yres_virtual, fb_fix.line_length, fb_fix.smem_len);

	//Second: mmap
	void *addr = mmap(NULL, fb_fix.smem_len, PROT_READ|PROT_WRITE, MAP_SHARED, fd, 0);
	if(addr == (void *)-1){
		printf("failed to mmap memory for framebuffer.\n");
		return;
	}

	if((fb_var.xoffset != 0)||(fb_var.yoffset != 0))
	{
		fb_var.xoffset = 0;
		fb_var.yoffset = 0;
		if(ioctl(fd, FBIOPAN_DISPLAY, &fb_var) < 0) {
			printf("FBIOPAN_DISPLAY framebuffer failed\n");
		}
	}

	LCD_FB_FD = fd;
	LCD_FB_BUF = addr;
	LCD_FB_LINELEN = fb_fix.line_length;

	//set empty
	AREA_SET_EMPTY(&update_area);
	return;
}

static void _copy_area(int *dst, int *src, struct area *pa)
{
	int x, y, w, h;
	x = pa->x1; w = pa->x2-x;
	y = pa->y1; h = pa->y2-y;
	char *psrc = (char *)src + y*(SCREEN_WIDTH*4) + x*4;
	char *pdst = (char *)dst + y*LCD_FB_LINELEN + x*4;
	while(h-- > 0){
		memcpy(pdst, psrc, w*4);
		psrc += SCREEN_WIDTH*4;
		pdst += LCD_FB_LINELEN;
	}
}

static int _check_area(struct area *pa)
{
	if(pa->x2 == 0) return 0; //is empty

	if(pa->x1 < 0) pa->x1 = 0;
	if(pa->x2 > SCREEN_WIDTH) pa->x2 = SCREEN_WIDTH;
	if(pa->y1 < 0) pa->y1 = 0;
	if(pa->y2 > SCREEN_HEIGHT) pa->y2 = SCREEN_HEIGHT;

	if((pa->x2 > pa->x1) && (pa->y2 > pa->y1))
		return 1; //no empty

	//set empty
	AREA_SET_EMPTY(pa);
	return 0;
}

void fb_update(void)
{
	if(_check_area(&update_area) == 0) return; //is empty
	_copy_area(LCD_FB_BUF, DRAW_BUF, &update_area);
	AREA_SET_EMPTY(&update_area); //set empty
	return;
}

/*======================================================================*/

static void * _begin_draw(int x, int y, int w, int h)
{
	int x2 = x+w;
	int y2 = y+h;
	if(update_area.x1 > x) update_area.x1 = x;
	if(update_area.y1 > y) update_area.y1 = y;
	if(update_area.x2 < x2) update_area.x2 = x2;
	if(update_area.y2 < y2) update_area.y2 = y2;
	return DRAW_BUF;
}

void fb_draw_pixel(int x, int y, int color)
{
	if(x<0 || y<0 || x>=SCREEN_WIDTH || y>=SCREEN_HEIGHT) return;
	int *buf = _begin_draw(x,y,1,1);
/*---------------------------------------------------*/
	*(buf + y*SCREEN_WIDTH + x) = color;
/*---------------------------------------------------*/
	return;
}

void fb_draw_rect(int x, int y, int w, int h, int color)
{
    if(w <= 0 || h <= 0) return;

    /* Clip before indexing. Widen the sums to avoid signed-int overflow. */
    int64_t left = x;
    int64_t top = y;
    int64_t right = (int64_t)x + w;
    int64_t bottom = (int64_t)y + h;

    if(left < 0) left = 0;
    if(top < 0) top = 0;
    if(right > SCREEN_WIDTH) right = SCREEN_WIDTH;
    if(bottom > SCREEN_HEIGHT) bottom = SCREEN_HEIGHT;
    if(left >= right || top >= bottom) return;

    x = (int)left;
    y = (int)top;
    w = (int)(right - left);
    h = (int)(bottom - top);
    int *buf = _begin_draw(x, y, w, h);

    for(int row = y; row < y + h; ++row) {
        int *pixel = buf + row * SCREEN_WIDTH + x;
        for(int column = 0; column < w; ++column) {
            pixel[column] = color;
        }
    }
    return;
}

void fb_draw_line(int x1, int y1, int x2, int y2, int color)
{
    int64_t dx = (int64_t)x2 - x1;
    int64_t dy = (int64_t)y2 - y1;
    int steep = llabs(dy) > llabs(dx);

    /* Use the longer axis, ordered consistently for reversed endpoints. */
    int64_t major1 = steep ? y1 : x1;
    int64_t major2 = steep ? y2 : x2;
    int64_t minor1 = steep ? x1 : y1;
    int64_t minor2 = steep ? x2 : y2;
    if(major1 > major2) {
        int64_t temporary = major1;
        major1 = major2;
        major2 = temporary;
        temporary = minor1;
        minor1 = minor2;
        minor2 = temporary;
    }

    uint64_t length = (uint64_t)(major2 - major1);
    if(length == 0) {
        fb_draw_pixel(x1, y1, color);
        return;
    }

    int direction = minor2 < minor1 ? -1 : 1;
    uint64_t minor_distance = (uint64_t)llabs(minor2 - minor1);
    int64_t limit = steep ? SCREEN_HEIGHT : SCREEN_WIDTH;
    int64_t first = major1 < 0 ? 0 : major1;
    int64_t last = major2 >= limit ? limit - 1 : major2;
    if(first > last) return;

    /*
     * Integer error accumulation, rounded to the nearest pixel.
     * Preserve the error phase when skipping off-screen major coordinates.
     * For 32-bit int endpoints, this product and sum fit in uint64_t.
     * The loop visits at most SCREEN_WIDTH or SCREEN_HEIGHT coordinates.
     */
    uint64_t numerator = minor_distance * (uint64_t)(first - major1)
                       + length / 2;
    int64_t minor = minor1 + direction * (int64_t)(numerator / length);
    uint64_t remainder = numerator % length;

    for(int64_t major = first; major <= last; ++major) {
        if(steep) {
            fb_draw_pixel((int)minor, (int)major, color);
        } else {
            fb_draw_pixel((int)major, (int)minor, color);
        }
        remainder += minor_distance;
        if(remainder >= length) {
            remainder -= length;
            minor += direction;
        }
    }
    return;
}

/* Blend one channel over an opaque framebuffer, with exact 0/255 endpoints. */
static unsigned blend_channel(unsigned src, unsigned dst, unsigned alpha)
{
    return (src * alpha + dst * (255-alpha) + 127) / 255;
}

void fb_draw_image(int x, int y, fb_image *image, int color)
{
    if(!image || !image->content || image->pixel_w <= 0 || image->pixel_h <= 0) return;
    int bytes = image->color_type == FB_COLOR_ALPHA_8 ? 1 : 4;
    if(image->color_type != FB_COLOR_RGB_8880 &&
       image->color_type != FB_COLOR_RGBA_8888 &&
       image->color_type != FB_COLOR_ALPHA_8) return;
    if(image->line_byte <= 0 || (int64_t)image->pixel_w * bytes > image->line_byte) return;

    int64_t left = x, top = y;
    int64_t right = (int64_t)x + image->pixel_w;
    int64_t bottom = (int64_t)y + image->pixel_h;
    if(left < 0) left = 0;
    if(top < 0) top = 0;
    if(right > SCREEN_WIDTH) right = SCREEN_WIDTH;
    if(bottom > SCREEN_HEIGHT) bottom = SCREEN_HEIGHT;
    if(left >= right || top >= bottom) return;
    int ix = (int)(left-x), iy = (int)(top-y);
    int w = (int)(right-left), h = (int)(bottom-top);
    int *buf = _begin_draw((int)left, (int)top, w, h);
    const unsigned char *source = (const unsigned char *)image->content
        + (size_t)iy * image->line_byte + (size_t)ix * bytes;
    uint32_t foreground = (uint32_t)color;

    for(int row = 0; row < h; ++row) {
        uint32_t *dst = (uint32_t *)(buf + ((int)top+row)*SCREEN_WIDTH + (int)left);
        const unsigned char *src = source + (size_t)row * image->line_byte;
        if(image->color_type == FB_COLOR_RGB_8880) {
            memcpy(dst, src, (size_t)w * 4);
            continue;
        }
        for(int column = 0; column < w; ++column) {
            unsigned alpha, b, g, r;
            if(bytes == 1) {
                alpha = src[column];
                b = foreground & 255; g = (foreground >> 8) & 255; r = (foreground >> 16) & 255;
            } else {
                const unsigned char *p = src + column*4;
                b = p[0]; g = p[1]; r = p[2]; alpha = p[3];
            }
            if(alpha == 0) continue;
            if(alpha != 255) {
                uint32_t old = dst[column];
                b = blend_channel(b, old & 255, alpha);
                g = blend_channel(g, (old >> 8) & 255, alpha);
                r = blend_channel(r, (old >> 16) & 255, alpha);
            }
            dst[column] = UINT32_C(0xff000000) | (r << 16) | (g << 8) | b;
        }
    }
}

void fb_draw_border(int x, int y, int w, int h, int color)
{
	if(w<=0 || h<=0) return;
	fb_draw_rect(x, y, w, 1, color);
	if(h > 1) {
		fb_draw_rect(x, y+h-1, w, 1, color);
		fb_draw_rect(x, y+1, 1, h-2, color);
		if(w > 1) fb_draw_rect(x+w-1, y+1, 1, h-2, color);
	}
}

/** draw a text string **/
void fb_draw_text(int x, int y, char *text, int font_size, int color)
{
	fb_image *img;
	fb_font_info info;
	int i=0;
	int len = strlen(text);
	while(i < len)
	{
		img = fb_read_font_image(text+i, font_size, &info);
		if(img == NULL) break;
		fb_draw_image(x+info.left, y-info.top, img, color);
		fb_free_image(img);

		x += info.advance_x;
		i += info.bytes;
	}
	return;
}

